#!/usr/bin/env python3
"""Render the general chapters' geometry figures from real FerroCAD geometry.

The figures under ``docs/general/images/`` are two kinds of asset:

* hand-authored SVGs, generated by ``tools/generate_concept_diagrams.py``;
* viewport snapshots, generated here. These are rendered by
  ``ferrocad_snapshot`` — the same offscreen renderer the documentation
  screenshots use — from a spec built out of the real ``Part`` and ``Mesh``
  modules, so the picture cannot describe geometry the code does not produce.

Two chapters and the how-to guides share them: a how-to guide that builds a
shape can show the same figure the concept chapters use (the NURBS pages do,
for example).

``docs/general/images/manifest.json`` pins each PNG to the spec that produced it
and to the byte digest. ``--check`` is GPU-free: it verifies the manifest, the
committed PNG and that the generator itself has not changed since the capture.
When the ``Part`` module is importable it also rebuilds each spec and compares
the digest; without a kernel it says so and checks the rest.

Usage::

    LD_LIBRARY_PATH=.occt/prefix/lib PYTHONPATH=python \\
        python3 tools/generate_general_figures.py --capture
    LD_LIBRARY_PATH=.occt/prefix/lib PYTHONPATH=python \\
        python3 tools/generate_general_figures.py --capture --only text-3d
    python3 tools/generate_general_figures.py --check
    python3 tools/generate_general_figures.py --list

``--only`` re-renders one figure and leaves every other committed PNG alone.
That matters when the machine that captures uses a different adapter than the
one that produced the rest of the set: a full ``--capture`` would rewrite all of
them even though only one figure changed.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

TOOLS = Path(__file__).resolve().parent
REPO = TOOLS.parent
sys.path.insert(0, str(TOOLS))

import userdocs  # noqa: E402

OUT = REPO / "docs" / "general" / "images"
MANIFEST = OUT / "manifest.json"
MANIFEST_VERSION = 1

#: Positions come from a floating-point kernel; six decimals keep the spec digest
#: stable across processes without changing what is drawn.
PRECISION = 6


def _round(value: float) -> float:
    rounded = round(float(value), PRECISION)
    return 0.0 if rounded == 0.0 else rounded


def _quantize(value):
    """Round every float in a nested list/``dict`` structure."""
    if isinstance(value, float):
        return _round(value)
    if isinstance(value, dict):
        return {key: _quantize(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_quantize(item) for item in value]
    return value


def _flat_edges(facets) -> list[int]:
    """The unique edges of a triangle list, as a flat ``(a, b)`` index array."""
    pairs = {
        (min(a, b), max(a, b))
        for triangle in facets
        for a, b in (
            (triangle[0], triangle[1]),
            (triangle[1], triangle[2]),
            (triangle[2], triangle[0]),
        )
    }
    return [index for pair in sorted(pairs) for index in pair]


def _smooth_normals(positions, triangles) -> list[list[float]]:
    """Area-weighted vertex normals for a flat triangle-index array.

    The kernel's display mesh has positions and triangles but no normals; the
    renderer uses per-vertex normals for smooth shading. Edge-only positions get
    a zero normal (the renderer ignores it for lines).
    """
    accumulated = [[0.0, 0.0, 0.0] for _ in positions]
    for index in range(0, len(triangles), 3):
        a, b, c = triangles[index], triangles[index + 1], triangles[index + 2]
        pa, pb, pc = positions[a], positions[b], positions[c]
        u = [pb[k] - pa[k] for k in range(3)]
        v = [pc[k] - pa[k] for k in range(3)]
        cross = [
            u[1] * v[2] - u[2] * v[1],
            u[2] * v[0] - u[0] * v[2],
            u[0] * v[1] - u[1] * v[0],
        ]
        for corner in (a, b, c):
            accumulated[corner] = [
                accumulated[corner][k] + cross[k] for k in range(3)
            ]

    normals = []
    for normal in accumulated:
        length = math.sqrt(sum(component * component for component in normal)) or 1.0
        normals.append([component / length for component in normal])
    return normals


# ---------------------------------------------------------------------------
# Figure builders
# ---------------------------------------------------------------------------


def sphere_mesh_vs_brep() -> dict:
    """One radius-10 sphere, once stored as a mesh and once kept as B-Rep.

    Both halves come from the same ``Part.makeSphere(10)``; only the tessellation
    settings differ. The left half is tessellated coarsely (80 triangles) and kept
    in a real ``Mesh.Mesh`` — that is the representation a mesh file stores. The
    right half stays a B-Rep shape and is meshed finely for the viewport only,
    with smooth normals and the shape's own edge polylines.
    """
    import Mesh
    import Part

    shape = Part.makeSphere(10.0)

    # Left: the coarse tessellation, stored as a mesh. `Mesh.Mesh` accepts the
    # (points, facets) tuple directly, which is exactly upstream's API. Ask for the
    # coarse mesh before the fine one below: OCCT stores the triangulation on the
    # shape and only re-meshes when the request is finer, so the reverse order
    # would make the mesh half silently fine.
    coarse = Mesh.Mesh(shape.tessellate(2.0, 1.0))
    points, facets = coarse.Topology
    mesh_positions = [[point.x - 15.0, point.y, point.z] for point in points]
    mesh_triangles = [index for facet in facets for index in facet]

    # Right: the display mesh the viewport gets. Its positions cover faces, edges
    # and vertices; for a sphere every one of them has the same normal, p / r.
    display = shape.mesh(0.2, 0.2)
    # Turn the seam meridian away from the silhouette so it is visible. A sphere is
    # rotationally symmetric, so this changes the picture, not the geometry.
    angle = math.radians(-80.0)
    cos, sin = math.cos(angle), math.sin(angle)

    def turn(position: list[float]) -> list[float]:
        x, y = position[0], position[1]
        return [x * cos - y * sin, x * sin + y * cos, position[2]]

    brep_positions = []
    brep_normals = []
    for x, y, z in display["positions"]:
        rx, ry, rz = turn([x, y, z])
        brep_positions.append([rx + 15.0, ry, rz])
        brep_normals.append(turn([x / 10.0, y / 10.0, z / 10.0]))

    spec = {
        "size": [960, 420],
        "camera": {"eye": [0.0, -58.0, 18.0], "target": [0.0, 0.0, 0.0], "fov_y": 0.62},
        "shapes": [
            {
                "geometry": {
                    "mesh": {
                        "positions": mesh_positions,
                        "triangles": mesh_triangles,
                        "edges": _flat_edges(facets),
                    }
                },
                "color": [0.78, 0.78, 0.78, 1.0],
                "edge_color": [0.30, 0.30, 0.30, 1.0],
                "draw_mode": "shaded_edges",
            },
            {
                "geometry": {
                    "mesh": {
                        "positions": brep_positions,
                        "normals": brep_normals,
                        "triangles": display["triangles"],
                        "edges": display["edges"],
                    }
                },
                "color": [0.42, 0.62, 0.88, 1.0],
                "edge_color": [0.10, 0.30, 0.65, 1.0],
                "draw_mode": "shaded_edges",
            },
        ],
    }
    return _quantize(spec)


def _octahedron(center, radius: float) -> tuple[list[list[float]], list[int]]:
    """A small diamond marker: 6 vertices and 8 outward-wound triangles."""
    cx, cy, cz = center
    positions = [
        [cx + radius, cy, cz],
        [cx - radius, cy, cz],
        [cx, cy + radius, cz],
        [cx, cy - radius, cz],
        [cx, cy, cz + radius],
        [cx, cy, cz - radius],
    ]
    triangles = [
        0, 2, 4, 2, 1, 4, 1, 3, 4, 3, 0, 4,
        2, 0, 5, 1, 2, 5, 3, 1, 5, 0, 3, 5,
    ]
    return positions, triangles


def _surface_spec(
    surface,
    *,
    eye,
    target,
    cage: bool,
    size=(960, 520),
) -> dict:
    """A shaded surface, optionally with its control cage and pole markers."""
    display = surface.toShape().mesh(0.05, 0.1)
    positions = display["positions"]
    triangles = display["triangles"]

    shapes = [
        {
            "geometry": {
                "mesh": {
                    "positions": positions,
                    "normals": _smooth_normals(positions, triangles),
                    "triangles": triangles,
                    "edges": [],
                }
            },
            "color": [0.42, 0.62, 0.88, 1.0],
            "draw_mode": "shaded",
        }
    ]

    if cage:
        # The cage: the poles the surface was built from, joined in U and V.
        grid = [[(point.x, point.y, point.z) for point in row] for row in surface.getPoles()]
        rows, columns = len(grid), len(grid[0])
        cage_positions = [list(point) for row in grid for point in row]
        cage_edges: list[int] = []
        for u in range(rows):
            for v in range(columns):
                index = u * columns + v
                if v + 1 < columns:
                    cage_edges += [index, index + 1]
                if u + 1 < rows:
                    cage_edges += [index, index + columns]

        marker_positions: list[list[float]] = []
        marker_triangles: list[int] = []
        for point in cage_positions:
            corners, faces = _octahedron(point, 0.13)
            base = len(marker_positions)
            marker_positions += corners
            marker_triangles += [base + index for index in faces]

        shapes.append(
            {
                "geometry": {
                    "mesh": {
                        "positions": cage_positions,
                        "triangles": [],
                        "edges": cage_edges,
                    }
                },
                "color": [0.82, 0.86, 0.92, 1.0],
                "edge_color": [0.82, 0.86, 0.92, 1.0],
                "draw_mode": "wireframe",
            }
        )
        shapes.append(
            {
                "geometry": {
                    "mesh": {
                        "positions": marker_positions,
                        "triangles": marker_triangles,
                        "edges": [],
                    }
                },
                "color": [0.82, 0.86, 0.92, 1.0],
                "draw_mode": "shaded",
            }
        )

    return _quantize(
        {
            "size": list(size),
            "camera": {"eye": list(eye), "target": list(target), "fov_y": 0.62},
            "shapes": shapes,
        }
    )


def bspline_patch() -> dict:
    """A clamped bicubic B-spline patch and its control cage.

    The surface is a 4x4 grid of poles with degrees 3/3; the knot vectors are
    ``[0, 1]`` with multiplicity 4 at each end, which is the clamped form (the
    surface interpolates its corner poles). The cage is ``surface.getPoles()``
    joined along U and V, with a small marker at every pole. This is the figure
    the how-to guide builds step by step.
    """
    import Part

    poles = [
        [[0, 0, 0], [0, 3, 2], [0, 6, 2], [0, 9, 0]],
        [[3, 0, 2], [3, 3, 3], [3, 6, 3], [3, 9, 2]],
        [[6, 0, 2], [6, 3, 3], [6, 6, 3], [6, 9, 2]],
        [[9, 0, 0], [9, 3, 2], [9, 6, 2], [9, 9, 0]],
    ]
    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        poles, [4, 4], [4, 4], [0.0, 1.0], [0.0, 1.0], False, False, 3, 3
    )
    return _surface_spec(
        surface, cage=True, eye=[11.5, -12.5, 9.5], target=[4.5, 4.5, 1.5]
    )


def bspline_flat() -> dict:
    """A bilinear patch: four poles, degree 1, flat."""
    import Part

    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        [[[0, 0, 0], [2, 0, 0]], [[0, 1, 0], [2, 1, 0]]],
        [2, 2],
        [2, 2],
        [0.0, 1.0],
        [0.0, 1.0],
        False,
        False,
        1,
        1,
    )
    return _surface_spec(
        surface, cage=False, eye=[3.0, -3.4, 2.6], target=[1.0, 0.5, 0.0]
    )


def _shape_spec(
    shape,
    *,
    eye,
    target,
    edges: bool = False,
    size=(960, 520),
) -> dict:
    """A shaded closed shape (a solid), optionally with its edges drawn."""
    display = shape.mesh(0.05, 0.1)
    positions = display["positions"]
    triangles = display["triangles"]
    mesh = {
        "positions": positions,
        "normals": _smooth_normals(positions, triangles),
        "triangles": triangles,
        "edges": display["edges"] if edges else [],
    }
    return _quantize(
        {
            "size": list(size),
            "camera": {"eye": list(eye), "target": list(target), "fov_y": 0.62},
            "shapes": [
                {
                    "geometry": {"mesh": mesh},
                    "color": [0.42, 0.62, 0.88, 1.0],
                    "edge_color": [0.10, 0.30, 0.65, 1.0],
                    "draw_mode": "shaded_edges" if edges else "shaded",
                }
            ],
        }
    )


def bspline_slab() -> dict:
    """The wavy sheet extruded into a solid."""
    import math

    import Part

    poles = [
        [[u, v * 3.0, math.sin(2 * math.pi * u / 8) * 2.0] for v in range(4)]
        for u in range(8)
    ]
    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        poles,
        [4, 2, 2, 4],
        [4, 4],
        [0.0, 1 / 3, 2 / 3, 1.0],
        [0.0, 1.0],
        False,
        False,
        3,
        3,
    )
    solid = surface.toShape().extrude((0.0, 0.0, 3.0))
    return _shape_spec(solid, eye=[14.0, -10.0, 12.0], target=[4.0, 4.5, 1.5], edges=True)


def bspline_solid_tube() -> dict:
    """The closed tube capped at both ends and turned into a solid."""
    import math

    import Part

    poles = [
        [
            [
                2.0 * math.cos(2 * math.pi * v / 8),
                2.0 * math.sin(2 * math.pi * v / 8),
                u * 2.0,
            ]
            for v in range(8)
        ]
        for u in range(4)
    ]
    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        poles,
        [4, 4],
        [1] * 9,
        [0.0, 1.0],
        [index / 8 for index in range(9)],
        False,
        True,
        3,
        3,
    )
    tube = surface.toShape()
    caps = [Part.Face(Part.Wire([edge])) for edge in tube.Edges if edge.isClosed()]
    # The surface face points inward; reversing it makes the solid's normals
    # face outward, so the volume is positive instead of -61.
    shell = Part.makeShell([tube.reversed(), *caps])
    solid = Part.makeSolid(shell)
    return _shape_spec(solid, eye=[9.0, -11.0, 9.0], target=[0.0, 0.0, 3.0], edges=True)


def bspline_wavy() -> dict:
    """A wavy sheet from a generated 4 by 8 pole grid (degree 3/3)."""
    import math

    import Part

    poles = [
        [
            [u, v * 3.0, math.sin(2 * math.pi * u / 8) * 2.0]
            for v in range(4)
        ]
        for u in range(8)
    ]
    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        poles,
        [4, 2, 2, 4],
        [4, 4],
        [0.0, 1 / 3, 2 / 3, 1.0],
        [0.0, 1.0],
        False,
        False,
        3,
        3,
    )
    return _surface_spec(
        surface, cage=False, eye=[14.0, -10.0, 10.0], target=[4.0, 4.5, 0.0]
    )


def text_3d() -> dict:
    """Lowercase "ferrocad" raised on a plate, built the way the how-to does.

    ``Draft.make_shape_string`` returns a compound of planar faces (one per glyph,
    each counter a hole), so every face extrudes to a solid; the letters are fused
    and raised on a plate sized from the text's bounding box. The round letters
    overshoot the baseline, so the box — not the baseline — places the plate.
    """
    import pathlib

    import Draft
    import FreeCAD
    import Part

    font = (
        pathlib.Path(__file__).resolve().parents[1]
        / "crates"
        / "ferrocad_text"
        / "tests"
        / "fixtures"
        / "fonts"
        / "LiberationMono-Regular.ttf"
    )
    cap_height, depth, thickness, margin = 20.0, 2.0, 3.0, 2.0
    document = FreeCAD.newDocument("TextFigure")
    try:
        string = Draft.make_shape_string("ferrocad", str(font), cap_height, 1.0)
        solids = [face.extrude((0.0, 0.0, depth)) for face in string.Shape.Faces]
        letters = solids[0].multiFuse(solids[1:])
        box = letters.BoundBox
        plate = Part.makeBox(
            box.XLength + 2 * margin, box.YLength + 2 * margin, thickness
        )
        raised = letters.copy()
        raised.translate(
            FreeCAD.Vector(-box.XMin + margin, -box.YMin + margin, thickness)
        )
        result = plate.fuse(raised)
        bounds = result.BoundBox
    finally:
        FreeCAD.closeDocument(document.Name)

    center = [
        (bounds.XMin + bounds.XMax) / 2,
        (bounds.YMin + bounds.YMax) / 2,
        (bounds.ZMin + bounds.ZMax) / 2,
    ]
    # A single line of text is a very wide strip, so the view is high and tight:
    # at 65 degrees the letters' cap height still projects at ~90 %, while the
    # plate's depth fills the frame instead of shrinking into a thin band.
    size = (960, 320)
    aspect = size[0] / size[1]
    elevation, azimuth = math.radians(65.0), math.radians(10.0)
    direction = [
        -math.cos(elevation) * math.sin(azimuth),
        -math.cos(elevation) * math.cos(azimuth),
        math.sin(elevation),
    ]
    distance = (bounds.XLength / 0.75) / (2.0 * math.tan(0.31) * aspect)
    eye = [center[axis] + distance * direction[axis] for axis in range(3)]
    return _shape_spec(result, eye=eye, target=center, edges=True, size=size)


def bspline_tube() -> dict:
    """A closed tube: periodic in V, clamped in U."""
    import math

    import Part

    poles = [
        [
            [
                2.0 * math.cos(2 * math.pi * v / 8),
                2.0 * math.sin(2 * math.pi * v / 8),
                u * 2.0,
            ]
            for v in range(8)
        ]
        for u in range(4)
    ]
    surface = Part.BSplineSurface()
    surface.buildFromPolesMultsKnots(
        poles,
        [4, 4],
        [1] * 9,
        [0.0, 1.0],
        [index / 8 for index in range(9)],
        False,
        True,
        3,
        3,
    )
    return _surface_spec(
        surface, cage=False, eye=[9.0, -11.0, 9.0], target=[0.0, 0.0, 3.0]
    )


